create table if not exists public.user_integrations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,provider text not null,provider_account_email text,scopes text[] not null default '{}',access_token_encrypted text,refresh_token_encrypted text,token_expires_at timestamptz,status text not null default 'connected' check(status in('connected','expired','revoked','error')),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,provider));alter table public.user_integrations enable row level security;drop policy if exists "Users can view own integrations" on public.user_integrations;create policy "Users can view own integrations" on public.user_integrations for select to authenticated using(auth.uid()=user_id);drop policy if exists "Users can delete own integrations" on public.user_integrations;create policy "Users can delete own integrations" on public.user_integrations for delete to authenticated using(auth.uid()=user_id);revoke all on public.user_integrations from anon;grant select,delete on public.user_integrations to authenticated;